import jwt

def verify_jwt_token(token, secret_key):
    """
    Verifies a JWT token and returns the decoded payload if valid.

    :param token: The JWT token to be verified.
    :param secret_key: The secret key used for decoding the token.
    :return: Decoded payload if the token is valid, otherwise raises an exception.
