    def execute_transaction(self, create_query, update_queries):
        """
        Executes a database transaction with a creation query and multiple update queries.
        """
        try:
            with self.connection.cursor() as cursor:
                # Execute the creation query
                cursor.execute(create_query)
                new_id = cursor.lastrowid  # Assuming the creation returns an ID

                # Execute all update queries with the new ID
