import jwt
from datetime import datetime, timedelta

def create_access_token(user_id):
    """Create an access token for a user."""
    payload = {
        'user_id': user_id,
        'exp': datetime.utcnow() + timedelta(hours=1)
    }
    return jwt.encode(payload, 'secret_key', algorithm='HS256')

